import json
rows=[json.loads(l) for l in open('transcript.jsonl')]
skill_calls=[]
tools=[]
for i,r in enumerate(rows):
    if r.get('type')=='assistant':
        for b in r.get('message',{}).get('content',[]):
            if b.get('type')=='tool_use':
                tools.append((i,b['name']))
