                    print(f"{n:02d} [{i}] Write: {inp.get('file_path')}")
                elif b['name']=='Read':
                    print(f"{n:02d} [{i}] Read: {inp.get('file_path')}")
                else:
                    print(f"{n:02d} [{i}] {b['name']}: {str(inp)[:120]}")
